def reconnect_loop():
    attempt = 0
    while not connected:
        if server_hint: sleep(server_hint.after_ms); server_hint = None
        else: sleep(random.uniform(0, min(30_000, 500 * 2 ** attempt)))
        try:
            connect(); resubscribe(last_seq_by_topic); attempt = 0
        except (Timeout, HTTP429, HTTP503) as e:
            attempt += 1
            if isinstance(e, HTTP429): server_hint = e.retry_after

class OutboundQueue:
    def offer(self, frame):
        if frame.cls == LATEST:
            self.latest[frame.topic] = frame       # overwrite older value
            self.ready.add(frame.topic); return OK
        if len(self.reliable) >= 256:
            close(self.conn, code=4008, reason='slow_consumer_resync')
            return OVERFLOW
        self.reliable.append(frame); return OK

    def drain(self, sock):
        while sock.writable():
            f = self.reliable.popleft() if self.reliable else self.pop_latest()
            if f is None: break
            sock.write(f.bytes)                  # pre-serialized once per message

def subscribe(conn, topic):
    s = index.setdefault(topic, set())
    if not s: backbone.subscribe(topic, on_message)
    s.add(conn)

def unsubscribe(conn, topic):
    s = index.get(topic, set()); s.discard(conn)
    if not s:
        schedule(backbone.unsubscribe, topic, delay=30)   # hysteresis

def on_message(topic, msg):
    frame = serialize(msg)                               # once per node
    for c in index.get(topic, ()): c.queue.offer(frame)
